"""Aftermath Report art (your painted war room with two blank parchments).
img(name) gives the surface; scaled(name, w, h) a cached resized copy."""
import base64
import io
import pygame

# everything in report_bg.jpg pixels (1672 x 941)
ART_W, ART_H = 1672, 941
TITLE = (505, 55, 1165, 178)        # inside of the blank title plaque
PAGE_L = (322, 318, 770, 655)       # writing area on the left parchment (below its top flourish)
PAGE_R = (902, 318, 1350, 655)      # writing area on the right parchment
PAGE_TOP_L = (560, 278)             # top centre of the left parchment (heading)
PAGE_TOP_R = (1140, 278)
BUTTON = (622, 745, 1048, 806)      # the red button plate
LIGHTS = ((395, 120, 50), (1275, 120, 50))
PNG = {
  'report_bg': ('jpg', ''),
}
_C = {}


def has(name):
  return name in PNG


def img(name):
  s = _C.get(name)
  if s is None:
    ext, data = PNG[name]
    s = pygame.image.load(io.BytesIO(base64.b64decode(data)), 'art.' + ext)
    try:
      s = s.convert_alpha()
    except Exception:
      pass
    _C[name] = s
  return s


def scaled(name, w, h, smooth=True):
  k = (name, int(w), int(h))
  s = _C.get(k)
  if s is None:
    src = img(name)
    fn = getattr(pygame.transform, 'smoothscale', None) if smooth else None
    try:
      s = (fn or pygame.transform.scale)(src, (max(1, int(w)), max(1, int(h))))
    except Exception:
      s = pygame.transform.scale(src, (max(1, int(w)), max(1, int(h))))
    _C[k] = s
  return s
